:root{
  --bg:#FAF6EF; --bg-alt:#F3EDE2; --ink:#26221C; --muted:#6E6459;
  --accent:#1E5C4B; --accent-soft:#E4EEE9; --terra:#C1683C;
  --border:#E5DCCD; --card:#FFFEFB;
  --serif:"EB Garamond",Georgia,serif; --sans:"Inter",-apple-system,sans-serif;
}
*{margin:0;padding:0;box-sizing:border-box}
@media (prefers-reduced-motion: no-preference){html{scroll-behavior:smooth}}
:focus-visible{outline:2px solid var(--accent);outline-offset:2px;border-radius:2px}
.skip{position:absolute;left:-9999px;top:12px;z-index:100;background:var(--accent);color:#fff;padding:10px 18px;border-radius:8px;font-weight:600;text-decoration:none}
.skip:focus{left:12px}
body{font-family:var(--sans);background:var(--bg);color:var(--ink);line-height:1.7;font-size:17px}
h1,h2,h3{font-family:var(--serif);font-weight:600;line-height:1.2}
a{color:var(--accent)}
img{max-width:100%;display:block}
.wrap{max-width:1100px;margin:0 auto;padding:0 24px}
section{padding:96px 0}
.eyebrow{font-size:13px;letter-spacing:.14em;text-transform:uppercase;color:var(--terra);font-weight:600;margin-bottom:14px}
.sec-title{font-size:clamp(28px,4vw,40px);margin-bottom:18px}
.sec-intro{color:var(--muted);max-width:640px;margin-bottom:48px}

/* Placeholder marker, remove class when real content is in */
.ph{background:#FFF3D6;outline:2px dashed #D9B96A;outline-offset:2px;border-radius:4px;padding:0 4px}

/* Nav */
nav{position:sticky;top:0;background:rgba(250,246,239,.92);backdrop-filter:blur(8px);border-bottom:1px solid var(--border);z-index:50}
.nav-inner{display:flex;align-items:center;justify-content:space-between;height:64px}
.wordmark{font-family:var(--serif);font-size:20px;font-weight:600;color:var(--ink);text-decoration:none}
.nav-links{display:flex;gap:28px;list-style:none}
.nav-links a{color:var(--ink);text-decoration:none;font-size:15px;font-weight:500}
.nav-links a:hover{color:var(--accent)}
.menu-btn{display:none;background:none;border:1px solid var(--border);border-radius:8px;padding:8px 12px;font-size:15px;cursor:pointer}

/* Hero */
.hero{padding:110px 0 90px}
.hero-grid{display:grid;grid-template-columns:1.15fr .85fr;gap:56px;align-items:center}
.hero h1{font-size:clamp(34px,5vw,54px)}
.hero h1 .sub{display:block;font-size:.55em;font-weight:500;color:var(--accent);margin-top:10px}
.mission{font-family:var(--serif);font-style:italic;font-size:clamp(19px,2.4vw,23px);color:var(--terra);margin:26px 0 18px}
.hero p.intro{color:var(--muted);max-width:540px}
.btn-row{display:flex;gap:14px;flex-wrap:wrap;margin-top:32px}
.btn{display:inline-block;padding:13px 26px;border-radius:10px;text-decoration:none;font-weight:600;font-size:15px;border:1.5px solid var(--accent);transition:all .15s}
.btn.primary{background:var(--accent);color:#fff}
.btn.primary:hover{background:#174a3c}
.btn.ghost{color:var(--accent)}
.btn.ghost:hover{background:var(--accent-soft)}
.hero-photo{aspect-ratio:4/5;border-radius:18px;background:var(--bg-alt);border:1px solid var(--border);overflow:hidden}
.hero-photo img{width:100%;height:100%;object-fit:cover}

/* Stats */
.stats{background:var(--card);border-top:1px solid var(--border);border-bottom:1px solid var(--border);padding:48px 0}
.stats-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:32px;text-align:center}
.stat .num{font-family:var(--serif);font-size:clamp(30px,3.5vw,44px);font-weight:600;color:var(--accent)}
.stat .label{font-size:13.5px;color:var(--muted);margin-top:6px}

/* About */
.about-grid{display:grid;grid-template-columns:1.5fr 1fr;gap:56px;align-items:start}
.about-grid p{margin-bottom:18px}
.facts{background:var(--card);border:1px solid var(--border);border-radius:14px;padding:28px}
.facts h3{font-size:18px;margin-bottom:16px}
.facts dl div{padding:10px 0;border-bottom:1px solid var(--border)}
.facts dl div:last-child{border-bottom:none}
.facts dt{font-size:12px;letter-spacing:.1em;text-transform:uppercase;color:var(--terra);font-weight:600}
.facts dd{font-size:15px;margin-top:2px}

/* Projects */
.section-alt{background:var(--bg-alt)}
.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:26px}
.card{background:var(--card);border:1px solid var(--border);border-radius:16px;overflow:hidden;display:flex;flex-direction:column;transition:box-shadow .2s,transform .2s}
.card:hover{box-shadow:0 8px 28px rgba(38,34,28,.10);transform:translateY(-2px)}
.card-img{aspect-ratio:16/9;background:var(--accent-soft);display:flex;align-items:center;justify-content:center;color:var(--muted);font-size:13px;text-align:center;padding:0;overflow:hidden}
.card-img img{width:100%;height:100%;object-fit:cover}
.card-img.empty{padding:12px}
.card-body{padding:24px;display:flex;flex-direction:column;gap:10px;flex:1}
.tag{align-self:flex-start;font-size:11.5px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--terra);background:#F7E8DD;padding:3px 10px;border-radius:99px}
.card h3{font-size:20px}
.meta{font-size:13.5px;color:var(--muted)}
.card p{font-size:15px}
.contrib{font-size:14px;padding-left:18px;color:var(--muted)}
.contrib li{margin-bottom:4px}
.impact-line{font-size:13.5px;font-weight:600;color:var(--accent);margin-top:auto;padding-top:8px;border-top:1px dashed var(--border)}

/* Writing */
.rows{border-top:1px solid var(--border)}
.row{display:grid;grid-template-columns:1fr auto;gap:8px 24px;padding:22px 4px;border-bottom:1px solid var(--border);align-items:baseline}
.row h3{font-size:18px}
.row .venue{font-size:14px;color:var(--muted)}
.row .desc{grid-column:1/-1;font-size:15px;color:var(--muted)}
.chip{font-size:13px;font-weight:600;color:var(--accent);text-decoration:none;white-space:nowrap}
.award{font-size:12px;font-weight:600;color:#fff;background:var(--terra);padding:2px 10px;border-radius:99px;letter-spacing:.04em;white-space:nowrap}

/* Teaching */
.teach-grid{display:grid;grid-template-columns:1fr 1fr;gap:48px;align-items:start}
.teach-facts{display:grid;gap:14px}
.tf{background:var(--card);border:1px solid var(--border);border-radius:12px;padding:18px 20px}
.tf h4{font-size:13px;letter-spacing:.1em;text-transform:uppercase;color:var(--terra);margin-bottom:6px}
.tf p{font-size:15px}
blockquote{font-family:var(--serif);font-style:italic;font-size:18px;background:var(--bg-alt);border-radius:10px;padding:18px 22px;margin-top:28px;color:var(--muted)}

/* Law */
.law{background:var(--ink);color:#F5F0E6}
.law .eyebrow{color:#E0A57E}
.law .sec-title{color:#fff}
.law .prose{max-width:680px}
.law p{margin-bottom:18px;color:#D8D0C2}
.law .pull{font-family:var(--serif);font-style:italic;font-size:20px;color:#F0C9A8}

/* Timeline */
.timeline{position:relative;max-width:760px;margin:0 auto;padding-left:36px}
.timeline::before{content:"";position:absolute;left:10px;top:6px;bottom:6px;width:2px;background:var(--border)}
.tl-item{position:relative;padding-bottom:40px}
.tl-item::before{content:"";position:absolute;left:-33px;top:7px;width:12px;height:12px;border-radius:50%;background:var(--terra);border:2.5px solid var(--bg)}
.tl-item .year{font-size:13px;font-weight:600;letter-spacing:.1em;color:var(--terra);text-transform:uppercase}
.tl-item h3{font-size:19px;margin:4px 0 6px}
.tl-item p{font-size:15px;color:var(--muted)}

/* Skills */
.skill-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:28px 40px}
.skill{border-top:1px solid var(--ink);padding:18px 0 0}
.skill h3{font-size:17px;margin-bottom:12px}
.pills{display:flex;flex-wrap:wrap;gap:8px}
.pill{font-size:13px;background:var(--accent-soft);color:var(--accent);padding:4px 12px;border-radius:99px;font-weight:500}
.langs{margin-top:32px;text-align:center;color:var(--muted);font-size:15px}

/* Gallery */
.gal-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}
.gal-item{background:var(--card);border:1px solid var(--border);border-radius:14px;overflow:hidden}
.gal-item img{width:100%;aspect-ratio:4/3;object-fit:cover}
.gal-item figcaption{font-size:13.5px;color:var(--muted);padding:12px 16px}

/* Contact */
.contact{text-align:center}
.contact .sec-intro{margin:0 auto 36px}

footer{border-top:1px solid var(--border);padding:36px 0;text-align:center;color:var(--muted);font-size:14px}

.reveal{opacity:0;transform:translateY(16px);transition:opacity .5s ease,transform .5s ease}
.reveal.in{opacity:1;transform:none}
@media (prefers-reduced-motion: reduce){
  .reveal{opacity:1;transform:none;transition:none}
  .card,.card:hover{transition:none;transform:none}
}

/* Current focus band */
.focus{background:var(--bg-alt);border-top:1px solid var(--border);border-bottom:1px solid var(--border);padding:36px 0}
.focus-inner{display:flex;align-items:center;gap:28px;flex-wrap:wrap}
.focus-inner p{font-size:16px;color:var(--muted);flex:1;min-width:260px;margin:0}
.focus-chips{display:flex;gap:10px;flex-wrap:wrap}
.focus-chip{font-size:13.5px;font-weight:600;color:var(--accent);background:var(--accent-soft);border:1px solid var(--accent);padding:6px 14px;border-radius:99px;text-decoration:none}
.focus-chip:hover{background:var(--accent);color:#fff}

/* Featured 2-col grid + status badge */
.cards.two{grid-template-columns:repeat(2,1fr)}
.status-badge{font-size:11.5px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--accent);background:var(--accent-soft);padding:3px 10px;border-radius:99px;align-self:flex-start}
.more-title{font-size:20px;font-family:var(--serif);margin:48px 0 8px;color:var(--muted)}
.mini-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 48px}
.mini{border-top:1px solid var(--border);padding:20px 0}
.mini h3{font-size:17px;font-family:var(--sans);font-weight:600}
.mini .meta{font-size:13px;margin:2px 0 6px}
.mini p{font-size:14.5px;color:var(--muted)}

/* Legal studies */
.legal-grid{display:grid;grid-template-columns:1.2fr 1fr;gap:48px;align-items:start}
.course-list{list-style:none;display:grid;gap:10px}
.course-list li{background:var(--card);border:1px solid var(--border);border-radius:10px;padding:12px 18px;font-size:15px}

/* Civic service band */
.civic{padding:64px 0}
.civic-card{background:var(--card);border:1px solid var(--border);border-radius:16px;padding:36px 40px;max-width:820px;margin:0 auto}
.civic-card h3{font-size:20px;margin-bottom:12px}
.civic-card p{font-size:15.5px;color:var(--muted)}

/* Disclaimer */
.disclaimer{font-size:13.5px;color:var(--muted);background:var(--bg-alt);border:1px solid var(--border);border-radius:10px;padding:14px 18px;max-width:720px}

/* Project subpages */
.proj-hero{padding:80px 0 56px;border-bottom:1px solid var(--border)}
.proj-hero .meta-line{font-size:15px;color:var(--muted);margin-top:14px}
.proj-hero .lede{font-size:19px;color:var(--muted);max-width:720px;margin-top:20px}
.backlink{display:inline-block;font-size:14px;font-weight:600;text-decoration:none;margin-bottom:24px}
.proj-section{padding:56px 0}
.proj-section h2{font-size:26px;margin-bottom:16px}
.proj-section p{max-width:720px;margin-bottom:16px}
.proj-section ul{max-width:720px;padding-left:22px;margin-bottom:16px}
.proj-section li{margin-bottom:8px}
figure.photo{background:var(--card);border:1px solid var(--border);border-radius:14px;overflow:hidden;margin:28px 0}
figure.photo img{width:100%}
figure.photo figcaption{font-size:13.5px;color:var(--muted);padding:12px 18px}
.photo-pair{display:grid;grid-template-columns:1fr 1fr;gap:22px}
.note{font-size:13.5px;color:var(--muted);background:var(--bg-alt);padding:12px 16px;border-radius:8px;max-width:720px}

@media(max-width:900px){
  .hero-grid,.about-grid,.teach-grid,.photo-pair,.legal-grid,.cards.two{grid-template-columns:1fr}
  .hero-grid{gap:36px}
  .hero-photo{order:-1;max-width:340px;aspect-ratio:1}
  .cards,.skill-grid,.gal-grid{grid-template-columns:1fr 1fr}
  .mini-grid{grid-template-columns:1fr}
  .stats-grid{grid-template-columns:repeat(2,1fr)}
  .nav-links{display:none;position:absolute;top:64px;left:0;right:0;background:var(--bg);flex-direction:column;padding:20px 24px;gap:18px;border-bottom:1px solid var(--border)}
  .nav-links.open{display:flex}
  .menu-btn{display:block}
}
@media(max-width:600px){
  .cards,.skill-grid,.gal-grid{grid-template-columns:1fr}
  section{padding:72px 0}
  .btn{width:100%;text-align:center;padding:14px}
  .btn-row{flex-direction:column}
}
